    print(f"Shape: cNvSpPr found: {cNvSpPr is not None}")
    if cNvSpPr is not None:
        print(f"  txBox value: {cNvSpPr.get('txBox')}")
        if cNvSpPr.get('txBox') == '1':
            print(f"  -> Found text box!")
